// regra — provedor por parâmetro (ADR-012): simulado | gravado | claude | openai. Só claude/openai gastam.
// origem simulado/gravado nunca é canônica nem vira vigente fora de ensaio (T15; db/004 CHECK, db/005 trigger).
const ORIGEM = { simulado: 'simulado', gravado: 'gravado', claude: 'api', openai: 'api' };
const c = $input.first().json || {};
const pedido = $('Chamado pelo W20').first().json;
if (!c.controle) throw new Error('licitação não existe: ' + pedido.controle);
const cfg = c.cfg || {};
// db/033: o pedido do botão "Extrair com GPT" vale para esta licitação e esta execução; o global fica como está
const provedor = String(c.provedor_pedido || (cfg.provedor ?? ''));
if (!(provedor in ORIGEM)) throw new Error(`configuracao.provedor inválido: '${provedor}' (simulado | gravado | claude | openai)`);
// db/037: o botão escolhe modelo e esforço (validados pela API: api/modelos_ia.py); sem escolha, a configuração
const modelo = c.modelo_pedido ? String(c.modelo_pedido)
  : (provedor === 'openai' ? String(cfg.modelo_openai || cfg.modelo) : String(cfg.modelo));
const ids = c.ids || [];
const cobertos = new Set(c.cobertos || []);
const pendentes = c.parcial_id ? ids.filter((i) => !cobertos.has(i)) : [];
return [{ json: {
  controle: c.controle, estado: c.estado, leitura_id: c.leitura_vigente_id, modalidade: c.modalidade,
  provedor, origem: ORIGEM[provedor], modelo, pedido_ia: !!c.provedor_pedido,
  effort: String(c.effort_pedido || cfg.effort || 'high'), lote: Number(cfg.lote || 6), k_rag: Number(cfg.k_rag || 6),
  max_tokens: Number(c.max_tokens_pedido || cfg.max_tokens || 16000), max_extracoes: Number(cfg.max_extracoes || 4),
  teto_brl_dia: c.teto_brl_dia == null ? null : Number(c.teto_brl_dia),
  parcial_id: (c.parcial_id && pendentes.length) ? c.parcial_id : null,
  ids_pendentes: (c.parcial_id && pendentes.length) ? pendentes : null,
  workflow_execucao_id: Number.isFinite(Number(pedido.workflow_execucao_id)) && pedido.workflow_execucao_id !== null
    && pedido.workflow_execucao_id !== '' ? Number(pedido.workflow_execucao_id) : null,
} }];

return [{ json: { ok: true, continuar: false, adiado: true, estado: $json.estado,
  controle: $('Parâmetros da extração').first().json.controle, motivo: 'W23: sem vaga; nova tentativa em 10 min',
  proxima_tentativa_em: $json.proxima_tentativa_em } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const site = String($env.FOPA_SITE_PUBLIC_URL || '').replace(/\/+$/, '');
const n8nBase = String($env.WEBHOOK_URL || '').replace(/\/+$/, '');
const linkExecucao = `${n8nBase}/workflow/${$workflow.id}/executions/${$execution.id}`;
// regra — teto do dia (orcamento.teto_brl_dia, db/007) com reserva de R$ 6,56 por extração em curso (db/019):
// o aviso vai para a fila com o link do admin do site, onde o teto se muda
const p = $('Parâmetros da extração').first().json;
const teto = Number(p.teto_brl_dia).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
return [{ json: { controle: p.controle,
  assunto: `[FOPA] Teto de gasto do dia atingido (R$ ${teto})`,
  corpo_html: `<p>A extração de ${esc(p.controle)} esperou: o gasto do dia mais as extrações em curso (R$ 6,56 de reserva`
    + ` cada) passaria do teto de R$ ${esc(teto)}. Nova tentativa em 1 h.</p>`
    + `<p><a href="${esc(site)}/admin">Mudar o teto no admin do site</a> · `
    + `<a href="${esc(site)}/licitacao/${esc(String(p.controle).replace('/', '-'))}">a licitação</a> · `
    + `<a href="${esc(linkExecucao)}">execução ${esc($execution.id)} no n8n</a></p>` } }];

return [{ json: { ok: true, continuar: false, adiado: true, estado: $json.estado,
  controle: $('Parâmetros da extração').first().json.controle, motivo: 'W23: teto de gasto do dia atingido',
  proxima_tentativa_em: $json.proxima_tentativa_em, email_id: $json.email_id ?? null } }];

// regra — recusada pela guarda da fila (fora do escopo, fora do recorte de 2026, estado que não extrai):
// nenhum provedor foi chamado e nada foi gravado (db/019:37-60)
const p = $('Parâmetros da extração').first().json;
return [{ json: { ok: false, continuar: false, recusada: true, estado: p.estado, controle: p.controle,
  motivo: 'W23: ' + $json.motivo } }];

// Um item por lote (ids + sha do corpo); o corpo em si fica no nó POST /prompt e é lido na hora de chamar,
// para não multiplicar 180 mil caracteres pelos nós da execução. Rodada 0 = o lote normal (db/050).
const lotes = $('POST /prompt').first().json.body.lotes;
return lotes.map((l, i) => ({ json: { lote_idx: i, ids: l.ids, request_sha256: l.request_sha256, tentativa: 0,
  rodada: 0 } }));

// regra — 3 chamadas EM SÉRIE, uma por lote (ADR-009; 60_pico_taxa). Vem do laço (tentativa 0) ou da espera de retentativa.
// A rodada (db/050: 0 = o lote normal; 1..N-1 = o reforço do Best-of-N) passa adiante, também na retentativa.
const i = $input.first().json;
return [{ json: { lote_idx: i.lote_idx, ids: i.ids, request_sha256: i.request_sha256,
  tentativa: (i.tentativa || 0) + 1, t0: Date.now(), rodada: i.rodada || 0 } }];

// regra — parse equivalente a scripts/fopa/modelos.py:238-245, mais o que a v2 não checava (plano §5 W23 passo 11):
// só blocos type=text (nunca content[0]: pode ser thinking); refusal → "recusa"; max_tokens → "truncado" (sem
// retentar com mais tokens: mantém a linha de base medida); o JSON tem de cobrir os ids do lote.
// regra — retentativa só em 408/429/500/502/503/529 e rede, até 3 tentativas, 30 s ou retry-after (plano §5 W23 passo 10)
const RETENTAVEIS = [408, 429, 500, 502, 503, 529];
const r = $input.first().json || {};
const lote = $('Preparar chamada').first().json;
const p = $('Parâmetros da extração').first().json;
const segundos = Math.round(Date.now() - lote.t0) / 1000;
const status = r.statusCode ?? null;
let erro = null, retentavel = false, espera_s = 30;
let envelope = null, stop_reason = null, usage = {};
if (r.error) {
  erro = 'sem resposta (rede/timeout): ' + String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 300);
  retentavel = true;
} else if (status !== 200) {
  const corpo = typeof r.body === 'string' ? r.body : JSON.stringify(r.body ?? '');
  erro = `HTTP ${status}: ${corpo.slice(0, 300)}`;
  retentavel = RETENTAVEIS.includes(status);
  const ra = Number((r.headers || {})['retry-after']);
  if (Number.isFinite(ra) && ra > 0) espera_s = Math.min(Math.ceil(ra), 60);
  envelope = (r.body && typeof r.body === 'object') ? r.body : { erro: corpo.slice(0, 2000) };
} else {
  envelope = typeof r.body === 'string' ? JSON.parse(r.body) : (r.body || {});
  let texto = '';
  if (p.provedor === 'openai') {
    // Responses API (ADR-012): output[].content[] do tipo output_text; incompleto por max_output_tokens = truncado
    const saidas = (envelope.output || []).flatMap((o) => o.content || []);
    const inc = envelope.incomplete_details && envelope.incomplete_details.reason;
    stop_reason = saidas.some((x) => x.type === 'refusal') ? 'refusal'
      : envelope.status === 'completed' ? 'end_turn'
      : (inc === 'max_output_tokens' ? 'max_tokens' : String(envelope.status || 'desconhecido'));
    texto = envelope.output_text || saidas.filter((x) => x.type === 'output_text').map((x) => x.text).join('');
    const u = envelope.usage || {};
    const cache = (u.input_tokens_details || {}).cached_tokens || 0;
    // input_tokens SOMA a entrada nova, a gravada e a lida no cache (fatura de 23/09); a gravada custa 1,25x
    // (US$ 5/M no gpt-5.6-sol): vai para cache_creation, nunca fica na entrada (medição da v3.1, 28/09)
    const gravado = (u.input_tokens_details || {}).cache_write_tokens || 0;
    usage = { input_tokens: Math.max((u.input_tokens || 0) - cache - gravado, 0), output_tokens: u.output_tokens || 0,
              cache_creation_input_tokens: gravado, cache_read_input_tokens: cache };
  } else {
    stop_reason = envelope.stop_reason ?? null;
    texto = (envelope.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
    usage = envelope.usage || {};
  }
  if (stop_reason === 'refusal') erro = 'recusa do modelo (stop_reason=refusal)';
  else if (stop_reason === 'max_tokens') erro = 'truncado (stop_reason=max_tokens)';
  else if (stop_reason !== 'end_turn') erro = `stop_reason inesperado: ${stop_reason}`;
  if (!erro) {
    try {
      const dados = JSON.parse(texto);
      const vieram = new Set((dados.respostas || []).map((x) => x.id));
      const faltam = lote.ids.filter((id) => !vieram.has(id));
      if (faltam.length) erro = 'lote incompleto: faltam ' + faltam.join(', ');
    } catch (e) {
      erro = 'a resposta não é JSON: ' + String(e.message).slice(0, 120);
    }
  }
}
// a rodada (db/050) vai para o Gravar chamada e, no Falha no reforço?, decide se o lote que falhou derruba a extração
return [{ json: {
  lote_idx: lote.lote_idx, ids: lote.ids, request_sha256: lote.request_sha256, tentativa: lote.tentativa,
  rodada: lote.rodada || 0, http_status: status, stop_reason, envelope, usage, segundos,
  ok: !erro, erro, retentar: !!erro && retentavel && lote.tentativa < 3, espera_s,
} }];

// Best-of-N (v3.1, db/050): um item por lote do reforço, como o `Lotes`; o corpo fica no POST /reforco e é
// lido na hora de chamar. rodada > 0 faz os provedores lerem o corpo de lá (não do /prompt) e vai para o
// Gravar chamada; vindo daqui, o `Loop lotes` recomeça o conjunto (reset).
const r = $('POST /reforco').last().json.body;
return r.lotes.map((l, i) => ({ json: { lote_idx: i, ids: l.ids, request_sha256: l.request_sha256, tentativa: 0,
  rodada: Number(r.rodada) } }));

const p = $('Parâmetros da extração').first().json;
return [{ json: { ok: true, continuar: true, estado: 'respondida', controle: p.controle,
  execucao_id: $('Abrir execução').first().json.id, reaproveitada: $('Abrir execução').first().json.reaproveitada,
  provedor: p.provedor, origem: p.origem, modelo: p.modelo, chamadas: Number($json.chamadas),
  brl: $json.brl == null ? null : Number($json.brl),
  motivo: `W23: ${$json.chamadas} chamada(s) por ${p.provedor}` } }];

// Falha vira MOTIVO escrito, nunca silêncio. Vem do /prompt (sem execução aberta) ou de um lote que esgotou as tentativas.
const j = $input.first().json || {};
let motivo;
if ($('Interpretar resposta').isExecuted && j.chamada_id !== undefined) {
  const r = $('Interpretar resposta').first().json;
  motivo = `lote ${r.ids.join(',')} falhou após ${r.tentativa} tentativa(s): ${r.erro}`;
} else if (j.error) {
  motivo = '/prompt sem resposta: ' + String(j.error.message || JSON.stringify(j.error)).slice(0, 240);
} else {
  const corpo = typeof j.body === 'string' ? j.body : JSON.stringify(j.body ?? '');
  motivo = `/prompt respondeu HTTP ${j.statusCode}: ${corpo.slice(0, 300)}`;
}
return [{ json: { motivo: 'W23: ' + motivo,
  execucao_id: $('Abrir execução').isExecuted ? $('Abrir execução').first().json.id : null } }];

const m = $('Motivo da falha').first().json;
return [{ json: { ok: false, continuar: false, estado: 'erro_extracao',
  controle: $('Parâmetros da extração').first().json.controle, motivo: m.motivo, execucao_id: m.execucao_id } }];
